,"origen":{"tipo":"CHAT","ref":"2026-11-25/CMO/SALY-CMO-024","solicitante":"DUENO via Claude"},"condicion":{"op":"=","izq":{"hecho":"cmo_024_lotizacion"},"der":{"lit":true}},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"cmo_024_lotizacion":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"cmo_024_lotizacion":false},"esperado":false}]},"fuente":"CERRADA; 00_Decisiones_Carga_masiva.md § 7","dependencia":"—","casos_documentales":"Positiva: Procesamiento por sub-lotes; Negativa: No ignorar tamaño de archivo (diseño, no ejecutada)"},{"codigo":"SALY-CMO-025","hechos":["cmo_025_meta_archivo"],"paquete":{"tipo":"NUEVA","codigo":"SALY-CMO-025","clave":"cmo_meta_archivo","familia":"CARGA_MASIVA","naturaleza":"DEFINICION","clase":"BACKEND","alcance":"CARGA_MASIVA","modo":"SOLO_AQUI","dueno":"PRODUCTO","titulo":"Meta de archivo","descripcion":"Meta 10000 empleados por archivo; si demanda mucho tiempo bajar a 5000 y luego 3000; recomendar tamaño de partición. Definición de negocio; binding runtime pendiente.","efecto":"DEFINIR","autoridad":"D-23","impacto":"REVISAR","origen":{"tipo":"CHAT","ref":"2026-11-25/CMO/SALY-CMO-025","solicitante":"DUENO via Claude"},"condicion":{"op":"=","izq":{"hecho":"cmo_025_meta_archivo"},"der":{"lit":true}},"pruebas":[{"casuistica":"VALOR_TIPICO","entrada":{"cmo_025_meta_archivo":true},"esperado":true},{"casuistica":"VALOR_BORDE","entrada":{"cmo_025_meta_archivo":false},"esperado":false}]},"fuente":"CERRADA; 00_Decisiones_Carga_masiva.md § 7","dependencia":"DEPENDE SALY-CMO-024","casos_documentales":"Positiva: Meta y reducciones documentadas; Negativa: No fijar tamaño exacto de partición como decidido (diseño, no ejecutada)"},{"codigo":"SALY-CMO-026","hechos":["cmo_026_canales_b2b"],"paquete":{"tipo":"NUEVA","codigo":"SALY-CMO-026","clave":"cmo_canales_b2b","familia":"CARGA_MASIVA","naturaleza":"DEFINICION","clase":"BACKEND","alcance":"CARGA_MASIVA","modo":"SOLO_AQUI","dueno":"PRODUCTO","titulo":"Canales B2B relacionados","descripcion":"Portal dispone de carga individual, mantenimiento y baja masiva e individual con variantes como la carga; detalle fuera de alcance. Definición de negocio; binding runtime pendiente.","efecto":"DEFINIR","autoridad":"D-23","impacto":"REVISAR","origen":{"tipo":"CHAT","ref":"2026-11-25/CMO/SALY-CMO-026","solicitante":"DUENO via Claude"},"condicion":{"op":"=","izq":{"hecho":"cmo_026_canales_b2b"},"der":{"lit":true}},"pruebas":[{"casuistica":"VALOR_TIPICO","entrada":{"cmo_026_canales_b2b":true},"esperado":true},{"casuistica":"VALOR_BORDE","entrada":{"cmo_026_canales_b2b":false},"esperado":false}]},"fuente":"CERRADA; 00_Decisiones_Carga_masiva.md § 8","dependencia":"—","casos_documentales":"Positiva: Canales diferenciados; Negativa: No tratar baja como carga masiva (diseño, no ejecutada)"}]$pack$::jsonb; p jsonb; a jsonb; ans jsonb; cd text; t record; n int:=0; vectors int:=0;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM saly.nucleo_nodos WHERE codigo='EMPRESAS' AND padre='GLOBAL' AND nivel='AMBITO') OR NOT EXISTS(SELECT 1 FROM saly.nucleo_nodos WHERE codigo='CARGA_MASIVA' AND padre='EMPRESAS' AND nivel='MODULO') THEN RAISE EXCEPTION 'CMO_SCOPE_DRIFT'; END IF;
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 a:=p->'paquete'; cd:=p->>'codigo';
 ans:=saly.nucleo_regla_proponer_v1(a,true);
 IF ans->>'resultado' IS DISTINCT FROM 'CANDIDATA' OR (ans->>'version')::int IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'CMO_PROPOSAL_FAIL % %',cd,ans; END IF;
 FOR t IN SELECT entrada,esperado FROM saly.nucleo_regla_pruebas WHERE regla=cd AND version=1 LOOP
 IF saly.nucleo_eval_v1(a->'condicion',t.entrada) IS DISTINCT FROM t.esperado THEN RAISE EXCEPTION 'CMO_VECTOR_FAIL %',cd; END IF;
 vectors:=vectors+1; END LOOP;
 IF NOT EXISTS(SELECT 1 FROM saly.nucleo_aplicaciones WHERE regla=cd AND nodo='CARGA_MASIVA' AND modo='SOLO_AQUI') THEN RAISE EXCEPTION 'CMO_APPLICATION_FAIL %',cd; END IF;
 n:=n+1;
 END LOOP;
 IF n<>26 OR vectors<>52 OR (SELECT count(*) FROM saly.nucleo_reglas WHERE codigo LIKE 'SALY-CMO-%')<>26 OR EXISTS(SELECT 1 FROM saly.nucleo_regla_versiones WHERE regla LIKE 'SALY-CMO-%' AND estado<>'CANDIDATA') THEN RAISE EXCEPTION 'CMO_COUNT_FAIL'; END IF;
 RAISE NOTICE 'CMO_CANDIDATAS % VECTORES %',n,vectors;
END $cmo$;
COMMIT;
